/* UI for the unofficial demo. All data comes from data/*.json generated by seed.py. */
(function () {
  "use strict";
  const E = window.Engine;
  const $ = (sel, el = document) => el.querySelector(sel);
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const pct = (x) => (x * 100).toFixed(0) + "%";
  const EXAMPLES = ["Q09", "Q04", "Q07", "Q19", "Q24", "Q03", "Q25"];

  const state = {
    listings: [], byId: new Map(), evalSet: null, evalByQuery: new Map(),
    query: "Romantic cabin with a fireplace in the Smokies", cfgId: "nl-full",
    evalCfg: "nl-full", openRow: null,
    cmp: { query: "Family of 6 near the theme parks with a pool and game room",
      left: { ...E.PRESETS.baseline }, right: { ...E.PRESETS["nl-full"] } },
    ctx: {},
  };

  const cfgKey = (c) => [c.parser, c.synonyms, c.reviewEvidence].join("|");
  const evalCache = new Map();
  function evaluateCached(cfg) {
    const k = cfgKey(cfg);
    if (!evalCache.has(k)) evalCache.set(k, E.evaluate(state.evalSet, cfg, state.listings));
    return evalCache.get(k);
  }
  function cfgName(c) {
    const p = Object.values(E.PRESETS).find((p) => cfgKey(p) === cfgKey(c));
    return p ? p.label : "Custom (parser " + (c.parser ? "on" : "off") + ", synonyms " + (c.synonyms ? "on" : "off") + ", reviews " + (c.reviewEvidence ? "on" : "off") + ")";
  }

  // ---------- shared renderers ----------
  function highlightQuery(q, constraints) {
    const spans = constraints.map((c) => ({ ...c.span, syn: c.via === "synonym", ign: c.ignored })).sort((a, b) => a.start - b.start);
    let out = "", i = 0;
    for (const s of spans) {
      if (s.start < i) continue;
      out += esc(q.slice(i, s.start)) + `<mark class="${s.syn ? "syn" : ""}">${esc(q.slice(s.start, s.end))}</mark>`;
      i = s.end;
    }
    return out + esc(q.slice(i));
  }
  function constraintChips(parsed, cfg) {
    if (!cfg.parser) {
      return `<div class="understood">${parsed.tokens.map((t) => `<span class="chip">${esc(t)}</span>`).join("") || '<span class="hint">no tokens</span>'}</div>
        <p class="hint">Keyword baseline: the query is just a bag of words; no filters are applied.</p>`;
    }
    const chips = parsed.constraints.map((c) => {
      const cls = c.ignored ? "ignored" : c.hard ? "hard" : "soft";
      const title = c.ignored ? c.ignoredReason : `${c.hard ? "Hard filter" : "Soft preference"} from \u201c${c.span.text}\u201d (${c.via})`;
      return `<span class="chip ${cls}" title="${esc(title)}"><b>${esc(E.KIND_LABEL[c.kind])}:</b> ${esc(E.labelOf(c))}
        <span class="via">\u2190 \u201c${esc(c.span.text)}\u201d${c.via === "synonym" ? " · synonym" : ""}</span></span>`;
    });
    const unrec = parsed.unrecognized.map((w) => `<span class="chip unrec" title="Not understood by this configuration">${esc(w)}?</span>`);
    return `<div class="understood">${chips.join("") || '<span class="hint">No constraints recognized.</span>'}${unrec.join("")}</div>
      <div class="legend"><span><span class="chip hard">hard filter</span></span><span><span class="chip soft">soft preference (ranking)</span></span>
      <span><span class="chip ignored">ignored by config</span></span><span><span class="chip unrec">not understood</span></span></div>`;
  }
  function answerHtml(res, ctx) {
    return res.answer.map((s) => s.text !== undefined ? esc(s.text)
      : `<button class="cite" data-ctx="${ctx}" data-id="${esc(s.cite.id)}" data-field="${esc(s.cite.field)}" title="Open source record ${esc(s.cite.id)} \u2192 ${esc(s.cite.field)}">${esc(s.cite.label)}</button>`).join("");
  }
  function checkChips(r) {
    if (r.checks) return r.checks.map((x) => `<span class="chip ${x.ok ? "ok" : "bad"}">${x.ok ? "\u2713" : "\u2717"} ${esc(E.labelOf(x.constraint))}</span>`).join("");
    return r.tokenHits.map((h) => `<span class="chip">\u201c${esc(h.token)}\u201d in ${esc(h.fields.map((f) => f.replace(/^reviews\..*/, "review")).filter((v, i, a) => a.indexOf(v) === i).join(", "))}</span>`).join("");
  }
  function resultCards(res, ctx, gold, limit = 10) {
    if (!res.results.length) return `<div class="empty">No listings pass the hard filters.</div>`;
    return `<div class="results">${res.results.slice(0, limit).map((r, i) => {
      const L = r.listing;
      const g = gold ? (gold.has(L.id) ? "gold" : "notgold") : "";
      return `<div class="result ${g}">
        <div class="rank">${i + 1}</div>
        <div><h4>${esc(L.title)} <span class="meta">· ${esc(L.id)}</span>${gold ? (gold.has(L.id) ? ' <span class="chip ok">relevant (gold)</span>' : ' <span class="chip bad">not relevant</span>') : ""}</h4>
          <div class="meta">${esc(L.destination)}, ${esc(L.state)} · ${esc(L.type)} · ${L.bedrooms} BR · sleeps ${L.sleeps} · ${L.pet_friendly ? "pets OK" : "no pets"} · \u2605 ${L.rating}</div>
          <div class="checks">${checkChips(r)}</div></div>
        <div class="price">$${L.nightly_price}<small>per night · score ${r.score.toFixed(2)}</small>
          <button class="btn secondary trace" data-ctx="${ctx}" data-id="${esc(L.id)}">Trace</button></div>
      </div>`;
    }).join("")}</div>`;
  }
  function goldFor(query) {
    const q = state.evalByQuery.get(query.trim().toLowerCase());
    return q ? new Set(q.relevant_ids) : null;
  }
  function presetSelect(id, current) {
    return `<select id="${id}">${Object.values(E.PRESETS).map((p) => `<option value="${p.id}" ${p.id === current ? "selected" : ""}>${esc(p.label)}</option>`).join("")}</select>`;
  }
  function exampleChips(cls) {
    return `<div class="examples"><span class="hint" style="margin:0">Try:</span>${EXAMPLES.map((id) => {
      const q = state.evalSet.queries.find((x) => x.id === id);
      return `<button class="chip ${cls}" data-q="${esc(q.query)}">${esc(q.query)}</button>`;
    }).join("")}</div>`;
  }

  // ---------- 1. Search & trace ----------
  function renderSearch() {
    const cfg = E.PRESETS[state.cfgId];
    const res = E.search(state.query, cfg, state.listings);
    state.ctx.search = res;
    const gold = goldFor(state.query);
    $("#view").innerHTML = `
      <div class="steps"><span>\u2460 Ask in plain English</span><span>\u2461 See how the query was understood</span>
        <span>\u2462 Read the grounded answer \u2014 click any citation</span><span>\u2463 Trace each result back to its source record</span></div>
      <div class="card">
        <form class="searchbar" id="sform"><input id="q" value="${esc(state.query)}" placeholder="e.g. dog-friendly cabin in the Smokies with a hot tub for 6" autocomplete="off" />
          <button class="btn" type="submit">Search</button></form>
        ${exampleChips("ex")}
        <div class="config-select" style="margin-top:12px"><b>Configuration</b> ${presetSelect("cfg", state.cfgId)} <span class="hint" style="margin:0">${esc(cfg.blurb)}</span></div>
      </div>
      <div class="row">
        <div class="card"><h3>Understood as</h3><div class="qhl">${highlightQuery(state.query, res.parsed.constraints)}</div>${constraintChips(res.parsed, cfg)}</div>
        <div class="card"><h3>Grounded answer</h3><div class="answer">${answerHtml(res, "search")}</div>
          <p class="hint" style="margin-top:8px">Generated deterministically from the ranked records; every claim links to the record field it came from.</p></div>
      </div>
      <div class="card"><h2>Results <span class="hint">(${res.totalMatches} matched · showing top ${Math.min(10, res.results.length)}${gold ? " · this query is in the eval set, so gold labels are shown" : ""})</span></h2>
        ${resultCards(res, "search", gold)}</div>`;
    $("#sform").onsubmit = (e) => { e.preventDefault(); state.query = $("#q").value; renderSearch(); };
    $("#cfg").onchange = (e) => { state.cfgId = e.target.value; renderSearch(); };
    document.querySelectorAll(".ex").forEach((b) => (b.onclick = () => { state.query = b.dataset.q; renderSearch(); }));
  }

  // ---------- Trace drawer ----------
  function openTrace(ctx, id, focus) {
    const res = state.ctx[ctx];
    const r = res && res.results.find((x) => x.listing.id === id);
    const L = state.byId.get(id);
    const hl = new Set();
    let evidence = "";
    if (r && r.checks) {
      r.checks.forEach((x) => x.evidence.forEach((e) => hl.add(e.field)));
      evidence = `<ul class="evidence">${r.checks.map((x) => `<li><span class="chip ${x.ok ? "ok" : "bad"}">${x.ok ? "\u2713" : "\u2717"} ${esc(E.KIND_LABEL[x.constraint.kind])}: ${esc(E.labelOf(x.constraint))}</span>
        \u2190 query \u201c${esc(x.constraint.span.text)}\u201d \u2192 ${x.evidence.map((e) => `<code>${esc(e.field)}</code> = ${esc(e.value)}`).join("; ")}</li>`).join("")}</ul>`;
    } else if (r && r.tokenHits) {
      r.tokenHits.forEach((h) => h.fields.forEach((f) => hl.add(f)));
      evidence = `<ul class="evidence">${r.tokenHits.map((h) => `<li>token \u201c${esc(h.token)}\u201d \u2192 ${h.fields.map((f) => `<code>${esc(f)}</code>`).join(", ")}</li>`).join("")}</ul>`;
    }
    const rows = [["id", L.id], ["title", L.title], ["destination", L.destination + ", " + L.state], ["scenes", L.scenes.join(", ")],
      ["type", L.type], ["bedrooms", L.bedrooms], ["bathrooms", L.bathrooms], ["sleeps", L.sleeps], ["nightly_price", "$" + L.nightly_price],
      ["pet_friendly", String(L.pet_friendly)], ["amenities", L.amenities.join(", ")], ["tags", L.tags.join(", ") || "\u2014"],
      ["rating", L.rating + " (" + L.review_count + " reviews)"], ["description", L.description],
      ...L.reviews.map((rv) => ["reviews." + rv.id, `\u2605${rv.rating} \u201c${rv.text}\u201d \u2014 ${rv.author}, ${rv.date}`])];
    const d = $("#drawer");
    d.innerHTML = `<div class="dhead"><button id="dclose" aria-label="Close">\u2715</button><div class="demo-tag">Unofficial demo built with Devin - synthetic data</div>
        <h3>Source record ${esc(L.id)}</h3><div style="color:#c9d3ee;font-size:12.5px">${esc(L.title)} \u00b7 ${esc(cfgName(res ? res.config : E.PRESETS[state.cfgId]))}</div></div>
      <div class="dbody"><h3>How this result was justified</h3>${evidence || '<p class="hint">Not in the current result list.</p>'}
        <h3 style="margin-top:14px">Record (data/listings.json)</h3>
        <table>${rows.map(([k, v]) => `<tr data-field="${esc(k)}" class="${hl.has(k) || (k === "destination" && hl.has("destination")) ? "hl" : ""} ${k === focus ? "focus" : ""}"><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join("")}</table></div>`;
    d.classList.add("open"); d.setAttribute("aria-hidden", "false"); $("#scrim").classList.add("open");
    $("#dclose").onclick = closeTrace;
    const f = focus && d.querySelector(`tr[data-field="${CSS.escape(focus)}"]`);
    if (f) setTimeout(() => f.scrollIntoView({ block: "center", behavior: "smooth" }), 220);
  }
  function closeTrace() { $("#drawer").classList.remove("open"); $("#drawer").setAttribute("aria-hidden", "true"); $("#scrim").classList.remove("open"); }

  // ---------- 2. Evaluation ----------
  function kpis(s) {
    return `<div class="kpis">
      <div class="kpi"><div class="v">${pct(s.accuracy)}</div><div class="l">Top-1 accuracy (best result is relevant)</div></div>
      <div class="kpi"><div class="v">${pct(s.p5)}</div><div class="l">Precision@5 (normalized)</div></div>
      <div class="kpi"><div class="v">${pct(s.r10)}</div><div class="l">Recall@10</div></div>
      <div class="kpi"><div class="v">${pct(s.violation)}</div><div class="l">Top-5 results breaking a hard requirement</div></div>
      <div class="kpi"><div class="v">${s.zero}/${s.n}</div><div class="l">Queries with zero results</div></div></div>`;
  }
  function renderEval() {
    const cfg = E.PRESETS[state.evalCfg];
    const t0 = performance.now();
    const ev = evaluateCached(cfg);
    const ms = (performance.now() - t0).toFixed(0);
    state.ctx.eval = null;
    $("#view").innerHTML = `
      <div class="card"><div class="config-select"><b>Configuration</b> ${presetSelect("ecfg", state.evalCfg)}
        <button class="btn" id="rerun">Run evaluation</button><span class="hint" style="margin:0">${state.evalSet.queries.length} labeled queries \u00b7 ${state.listings.length} listings \u00b7 ran in ${ms} ms</span></div>
        <p class="hint" style="margin-top:10px">Gold labels come from hidden ground truth in <code>seed.py</code> (including \u201cvibes\u201d that only surface through review text), not from the search engine. Two queries are deliberately <i>known-hard</i> (negation, open-ended numbers).</p></div>
      ${kpis(ev.summary)}
      <div class="card" style="margin-top:16px"><h3>Top-1 accuracy by query type</h3>
        <table>${Object.entries(ev.byTag).sort().map(([k, v]) => `<tr><td style="width:160px">${esc(k)}</td><td style="width:60px">${pct(v.acc)}</td><td><div class="bar"><i style="width:${v.acc * 100}%"></i></div></td><td class="hint" style="width:90px">${v.n} queries</td></tr>`).join("")}</table></div>
      <div class="card"><h3>Per-query results <span style="text-transform:none;letter-spacing:0">(click a row to inspect)</span></h3>
        <table><thead><tr><th>ID</th><th>Query</th><th>Type</th><th>Gold</th><th>Top-1</th><th>P@5</th><th>Result</th></tr></thead><tbody>
        ${ev.rows.map((r) => `<tr class="expandable" data-row="${r.q.id}"><td>${r.q.id}</td><td>${esc(r.q.query)}</td><td>${r.q.tags.map((t) => `<span class="chip">${esc(t)}</span>`).join(" ")}</td>
          <td>${r.q.relevant_ids.length}</td><td>${esc(r.ids[0] || "\u2014")}</td><td>${pct(r.p5)}</td><td class="${r.hit1 ? "pass" : "fail"}">${r.hit1 ? "PASS" : "FAIL"}</td></tr>
          ${state.openRow === r.q.id ? detailRow(r) : ""}`).join("")}</tbody></table></div>`;
    $("#ecfg").onchange = (e) => { state.evalCfg = e.target.value; state.openRow = null; renderEval(); };
    $("#rerun").onclick = () => { evalCache.delete(cfgKey(cfg)); renderEval(); };
    document.querySelectorAll("tr.expandable").forEach((tr) => (tr.onclick = () => { state.openRow = state.openRow === tr.dataset.row ? null : tr.dataset.row; renderEval(); }));
  }
  function detailRow(r) {
    state.ctx["eval-" + r.q.id] = r.res;
    return `<tr class="detail"><td></td><td colspan="6">
      <div class="qhl">${highlightQuery(r.q.query, r.res.parsed.constraints)}</div>${constraintChips(r.res.parsed, r.res.config)}
      <p><b>Gold spec:</b> <code>${esc(JSON.stringify(r.q.gold))}</code> \u2192 relevant: ${r.q.relevant_ids.map((id) => `<button class="cite" data-ctx="eval-${r.q.id}" data-id="${id}" data-field="id">${id}</button>`).join(" ")}</p>
      <p><b>Grounded answer:</b> ${answerHtml(r.res, "eval-" + r.q.id)}</p>
      ${resultCards(r.res, "eval-" + r.q.id, new Set(r.q.relevant_ids), 5)}
      <p><button class="btn secondary open-search" data-q="${esc(r.q.query)}">Open in Search</button></p></td></tr>`;
  }

  // ---------- 3. Compare ----------
  function sidePanel(side) {
    const c = state.cmp[side];
    const preset = Object.values(E.PRESETS).find((p) => cfgKey(p) === cfgKey(c));
    return `<div class="config-select"><b>${side === "left" ? "Left" : "Right"}</b>
        <select data-side="${side}" class="cpreset">${Object.values(E.PRESETS).map((p) => `<option value="${p.id}" ${preset && preset.id === p.id ? "selected" : ""}>${esc(p.label)}</option>`).join("")}
        ${preset ? "" : '<option selected value="">Custom</option>'}</select></div>
      <div class="toggles" style="margin-top:8px">
        ${[["parser", "NL query parser"], ["synonyms", "Synonyms & paraphrases"], ["reviewEvidence", "Review evidence for vibes"]].map(([k, l]) =>
          `<label><input type="checkbox" data-side="${side}" data-k="${k}" ${c[k] ? "checked" : ""} ${k !== "parser" && !c.parser ? "disabled" : ""}/> ${l}</label>`).join("")}</div>`;
  }
  function renderCompare() {
    const { left, right, query } = state.cmp;
    const gold = goldFor(query);
    const rl = E.search(query, left, state.listings), rr = E.search(query, right, state.listings);
    state.ctx["cmp-left"] = rl; state.ctx["cmp-right"] = rr;
    const el = evaluateCached(left), er = evaluateCached(right);
    const metrics = [["Top-1 accuracy", "accuracy", true], ["Precision@5", "p5", true], ["Recall@10", "r10", true], ["Hard-requirement violations (top 5)", "violation", false]];
    const diffs = el.rows.map((a, i) => [a, er.rows[i]]).filter(([a, b]) => a.hit1 !== b.hit1);
    const col = (res, ctx) => `<div class="card"><h3>${esc(cfgName(res.config))}</h3>
        <div class="qhl">${highlightQuery(query, res.parsed.constraints)}</div>${constraintChips(res.parsed, res.config)}
        <p class="answer" style="font-size:14px">${answerHtml(res, ctx)}</p>${resultCards(res, ctx, gold, 5)}</div>`;
    $("#view").innerHTML = `
      <div class="card"><form class="searchbar" id="cform"><input id="cq" value="${esc(query)}" autocomplete="off" /><button class="btn" type="submit">Compare</button></form>
        ${exampleChips("cex")}
        <div class="row" style="margin-top:14px"><div>${sidePanel("left")}</div><div>${sidePanel("right")}</div></div></div>
      <div class="card cmp-metrics"><h3>Evaluation set (${el.summary.n} queries) \u2014 left vs right</h3>
        <table><thead><tr><th>Metric</th><th>Left</th><th></th><th>Right</th><th></th><th>\u0394 (right \u2212 left)</th></tr></thead><tbody>
        ${metrics.map(([l, k, up]) => { const a = el.summary[k], b = er.summary[k], d = b - a, good = up ? d > 0 : d < 0;
          return `<tr><td>${l}</td><td class="num">${pct(a)}</td><td><div class="bar"><i style="width:${a * 100}%"></i></div></td><td class="num">${pct(b)}</td>
            <td><div class="bar b"><i style="width:${b * 100}%"></i></div></td><td class="num delta ${d === 0 ? "" : good ? "up" : "down"}">${d >= 0 ? "+" : ""}${(d * 100).toFixed(0)} pts</td></tr>`; }).join("")}
        </tbody></table>
        <p class="hint" style="margin-top:10px">${diffs.length ? `${diffs.filter(([a, b]) => b.hit1).length} queries flip to PASS on the right, ${diffs.filter(([a]) => a.hit1).length} flip to FAIL:` : "Both configurations agree on every query."}</p>
        <div class="examples">${diffs.map(([a, b]) => `<button class="chip ${b.hit1 ? "ok" : "bad"} cex" data-q="${esc(a.q.query)}">${a.q.id} ${b.hit1 ? "\u2191" : "\u2193"} ${esc(a.q.query)}</button>`).join("")}</div></div>
      <div class="row">${col(rl, "cmp-left")}${col(rr, "cmp-right")}</div>`;
    $("#cform").onsubmit = (e) => { e.preventDefault(); state.cmp.query = $("#cq").value; renderCompare(); };
    document.querySelectorAll(".cex").forEach((b) => (b.onclick = () => { state.cmp.query = b.dataset.q; renderCompare(); window.scrollTo({ top: 0 }); }));
    document.querySelectorAll(".cpreset").forEach((s) => (s.onchange = () => { if (s.value) { state.cmp[s.dataset.side] = { ...E.PRESETS[s.value] }; renderCompare(); } }));
    document.querySelectorAll(".toggles input").forEach((i) => (i.onchange = () => {
      const c = { ...state.cmp[i.dataset.side], [i.dataset.k]: i.checked };
      if (!c.parser) { c.synonyms = false; c.reviewEvidence = false; }
      state.cmp[i.dataset.side] = c; renderCompare();
    }));
  }

  // ---------- routing ----------
  function route() {
    const tab = (location.hash || "#search").slice(1);
    document.querySelectorAll(".tabs a").forEach((a) => a.classList.toggle("active", a.dataset.tab === tab));
    closeTrace();
    if (tab === "eval") renderEval(); else if (tab === "compare") renderCompare(); else renderSearch();
  }
  document.addEventListener("click", (e) => {
    const t = e.target.closest(".cite, .trace");
    if (t) { e.stopPropagation(); openTrace(t.dataset.ctx, t.dataset.id, t.dataset.field || "title"); return; }
    const o = e.target.closest(".open-search");
    if (o) { state.query = o.dataset.q; state.cfgId = state.evalCfg; location.hash = "#search"; }
  }, true);
  $("#scrim").onclick = closeTrace;
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") closeTrace(); });
  window.addEventListener("hashchange", route);

  Promise.all([fetch("data/listings.json").then((r) => r.json()), fetch("data/eval_set.json").then((r) => r.json())]).then(([l, ev]) => {
    state.listings = l.listings;
    state.listings.forEach((L) => state.byId.set(L.id, L));
    state.evalSet = ev;
    ev.queries.forEach((q) => state.evalByQuery.set(q.query.toLowerCase(), q));
    route();
  }).catch((err) => { $("#view").innerHTML = `<div class="card">Could not load seeded data (${esc(err.message)}). Run <code>python3 seed.py</code> and serve this folder over HTTP.</div>`; });
})();
